// Extract total number of pages from the listing header
// Header pattern: "Found: 212 (Page 1 of 9)"
const html = $input.first().json.data || '';
const location_id = $('Split Countries').item.json.location_id;
const country_name = $('Split Countries').item.json.name;

const pageMatch = html.match(/Page\s+\d+\s+of\s+(\d+)/);
const totalPages = pageMatch ? parseInt(pageMatch[1]) : 1;

const foundMatch = html.match(/Found:\s*([\d,]+)/);
const totalFound = foundMatch ? parseInt(foundMatch[1].replace(',', '')) : 0;

console.log(`[${country_name}] Total pages: ${totalPages}, Total coasters: ${totalFound}`);

return [{
  json: {
    location_id,
    country_name,
    totalPages,
    totalFound
  }
}];

// Generate array of all page URLs for this country
const { location_id, country_name, totalPages } = $input.first().json;

const pages = [];
for (let page = 1; page <= totalPages; page++) {
  pages.push({
    url: `https://rcdb.com/r.htm?ot=2&ol=${location_id}&page=${page}`,
    page,
    location_id,
    country_name
  });
}

console.log(`[${country_name}] Generated ${pages.length} page URLs`);
return pages.map(p => ({ json: p }));

// Parse one listing page and extract coaster + park pairs
// Each table row has: coaster name/link in col 2, park name/link in col 3
//
// HTML pattern per row (simplified):
//   <td ...><a href="/1657.htm">Alpen Blitz</a></td>
//   <td ...><a href="/4946.htm">Playcenter São Paulo</a></td>

const html = $input.first().json.data || '';
const page = $input.first().json.page || '?';
const country_name = $input.first().json.country_name || '';

const results = [];

// Match table rows in the results table.
// The listing table rows contain two consecutive links: coaster href then park href.
// Strategy: find all <tr> blocks that contain exactly the coaster+park pattern.
// Pattern: two <a href="/NNN.htm"> within a <tr>, where the second is the park.

// Extract all <tr>...</tr> blocks
const rowRegex = /<tr[^>]*>([\s\S]*?)<\/tr>/gi;
let rowMatch;

while ((rowMatch = rowRegex.exec(html)) !== null) {
  const row = rowMatch[1];
  // Find all links /NNN.htm within this row
  const linkRegex = /href="\/(\d+)\.htm"[^>]*>([^<]+)<\/a>/g;
  const links = [];
  let linkMatch;
  while ((linkMatch = linkRegex.exec(row)) !== null) {
    links.push({ rcdb_id: linkMatch[1], name: linkMatch[2].trim() });
  }

  // A valid coaster row has at least 2 links: coaster (index 0) + park (index 1)
  // Additional links (city, state, country) may follow — we only need the first two
  if (links.length >= 2) {
    const coaster = links[0];
    const park = links[1];
    // Sanity check: skip navigation rows where names look like single words (About, Search, etc)
    // Real coaster names are usually longer or have spaces — but don't over-filter.
    // Instead, rely on the fact that listing rows always have at least 2 href=/NNN.htm links.
    results.push({
      coaster_rcdb_id: coaster.rcdb_id,
      coaster_name: coaster.name,
      park_rcdb_id: park.rcdb_id,
      park_name: park.name,
      country_name
    });
  }
}

console.log(`[${country_name}] Page ${page}: extracted ${results.length} coaster/park pairs`);
return results.map(r => ({ json: r }));

// Collect all coaster+park pairs from all pages and deduplicate
// Output 0: unique parks to fetch
// We store coasters in a global variable approach — 
// in n8n, we use the aggregate approach: all items arrive here together
// after the loop completes.

const allItems = $input.all();

const coastersMap = {};
const parksMap = {};

for (const item of allItems) {
  const d = item.json;
  if (!d.coaster_rcdb_id || !d.park_rcdb_id) continue;

  coastersMap[d.coaster_rcdb_id] = {
    coaster_rcdb_id: d.coaster_rcdb_id,
    coaster_name: d.coaster_name,
    park_rcdb_id: d.park_rcdb_id
  };

  parksMap[d.park_rcdb_id] = {
    rcdb_id: d.park_rcdb_id,
    name: d.park_name
  };
}

const parks = Object.values(parksMap);
const coasters = Object.values(coastersMap);

console.log(`Deduplicated: ${parks.length} unique parks, ${coasters.length} unique coasters`);

// Store coasters list in each park item so it can be accessed later
// n8n doesn't have shared state, so we attach coasters as metadata on first park
// and empty array on the rest — the coaster upsert node handles the full list independently.

// Return parks as main output; coasters are emitted via output index 1
return [
  parks.map(p => ({ json: { ...p, _all_coasters: coasters } })),
];

// Parse park page and extract: name, city, country, lat, lng
// Passes through rcdb_id and _all_coasters for downstream nodes.

const item = $input.first().json;

if (item.error || !item.data) {
  const rcdb_id = $('Deduplicate Parks & Coasters').item.json.rcdb_id;
  console.error(`[Park ${rcdb_id}] HTTP error:`, item.error || 'no data');
  return [{ json: { rcdb_id, name: null, city: null, country: null, latitude: null, longitude: null, _error: true } }];
}

const html = item.data;
const rcdb_id = $('Deduplicate Parks & Coasters').item.json.rcdb_id;
const _all_coasters = $('Deduplicate Parks & Coasters').item.json._all_coasters || [];

// Extract name from <h1>
const nameMatch = html.match(/<h1>([^<]+)<\/h1>/);
const name = nameMatch ? nameMatch[1].trim() : null;

// Extract lat/lng from Google Maps link
// Pattern: maps.google.com/maps/place/{lat},{lng}/@{lat},{lng},...
const coordMatch = html.match(/maps\.google\.com\/maps\/place\/(-?\d+\.\d+),(-?\d+\.\d+)/);
const latitude = coordMatch ? parseFloat(coordMatch[1]) : null;
const longitude = coordMatch ? parseFloat(coordMatch[2]) : null;

// Extract city and country from location breadcrumb links
// Pattern: <a href="/location.htm?id=NNN">City</a>, <a href="/location.htm?id=NNN">State</a>, <a href="/location.htm?id=NNN">Country</a>
// or without state: <a href="/location.htm?id=NNN">City</a>, <a href="/location.htm?id=NNN">Country</a>

const locationLinkRegex = /location\.htm\?id=\d+">([^<]+)<\/a>/g;
const locationParts = [];
let locMatch;
while ((locMatch = locationLinkRegex.exec(html)) !== null) {
  locationParts.push(locMatch[1].trim());
}

// locationParts order: [city, (state?), country]
let city = null;
let country = null;
if (locationParts.length >= 3) {
  city = locationParts[0];
  country = locationParts[locationParts.length - 1]; // last element is always country
} else if (locationParts.length === 2) {
  city = locationParts[0];
  country = locationParts[1];
} else if (locationParts.length === 1) {
  country = locationParts[0];
}

console.log(`[Park ${rcdb_id}] name=${name}, city=${city}, country=${country}, lat=${latitude}, lng=${longitude}`);

return [{
  json: {
    rcdb_id,
    name,
    city,
    country,
    latitude,
    longitude,
    _all_coasters,
    synced_at: new Date().toISOString()
  }
}];

// After all parks are upserted, emit all coasters for upsert.
// _all_coasters is attached to the first park item — we collect from all items
// and deduplicate again in case multiple parks carried the list.

const allItems = $input.all();

const coastersMap = {};
for (const item of allItems) {
  const coasters = item.json._all_coasters || [];
  for (const c of coasters) {
    if (c.coaster_rcdb_id) {
      coastersMap[c.coaster_rcdb_id] = c;
    }
  }
}

const coasters = Object.values(coastersMap);
console.log(`Emitting ${coasters.length} coasters for upsert`);
return coasters.map(c => ({ json: c }));

// Final summary log
const results = $input.all();
const errors = results.filter(r => r.json.error);
console.log(`[RCDB Scraper] Completed. Total coaster upserts: ${results.length}, errors: ${errors.length}`);
return [{ json: { done: true, total: results.length, errors: errors.length, timestamp: new Date().toISOString() } }];

// Error handler: log structured error and continue
const err = $input.first().json;
console.error('[RCDB Scraper Error]', JSON.stringify({
  message: err.message || 'Unknown error',
  node: err.node || 'unknown',
  timestamp: new Date().toISOString(),
  data: err
}, null, 2));
return [{ json: { error: true, message: err.message || 'unknown', timestamp: new Date().toISOString() } }];
